import sys

def findString(N, K):
    if N == 1:
        return "".join(str(i) for i in range(K))

    visited = set()
    result = []

    def dfs(node):
        for digit in range(K):
            edge = node + str(digit)
            if edge not in visited:
                visited.add(edge)
                dfs(edge[1:])
                result.append(digit)

    start = "0" * (N - 1)
    dfs(start)
    return start + "".join(map(str, reversed(result)))

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    K = int(input_data[1])
    print(findString(N, K))

if __name__ == "__main__":
    main()
